import math

def is_prime(n):
    if not isinstance(n, int):
        raise TypeError('Input must be an integer.')
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    limit = int(math.sqrt(n))
    for i in range(3, limit + 1, 2):
        if n % i == 0:
            return False
    return True

# Example usage (for testing, not part of the function itself)
