def calculate_bmi(weight_kg, height_m):
    'Calculates the Body Mass Index (BMI).'
    if not isinstance(weight_kg, (int, float)):
        raise TypeError('Weight must be a number.')
    if not isinstance(height_m, (int, float)):
        raise TypeError('Height must be a number.')
    if weight_kg <= 0:
        raise ValueError('Weight must be positive.')
    if height_m <= 0:
        raise ValueError('Height must be positive.')

    bmi = weight_kg / (height_m ** 2)
    return round(bmi, 2)

if __name__ == '__main__':
    # Example usage:
    w1, h1 = 70, 1.75
    result1 = calculate_bmi(w1, h1)
    print(f'Weight: {w1} kg, Height: {h1} m. BMI: {result1}')

    w2, h2 = 100, 2.0
    result2 = calculate_bmi(w2, h2)
    print(f'Weight: {w2} kg, Height: {h2} m. BMI: {result2}')

    # Test edge cases or errors
    try:
        calculate_bmi(0, 1.7)
    except ValueError as e:
        print(f'Error: {e}')

    try:
        calculate_bmi(70, 'invalid')
    except TypeError as e:
        print(f'Error: {e}')

