def simulate_queue(operations):
    queue = []
    for op_type, value in operations:
        if op_type == 'enqueue':
            queue.append(value)
        elif op_type == 'dequeue':
            if queue:
                queue.pop(0)
            else:
                print('Warning: Dequeue on an empty queue.')
        else:
            print(f'Error: Unknown operation type \'{op_type}\'. Skipping.')
    return queue

