def most_frequent_char(text: str) -> str:
    '''Finds the most frequent character in a string, ignoring spaces and case.'''
    char_counts = {}
    most_freq_char = ''
    max_count = 0

    lower_text = text.lower()  # 'converting to lowercase'

    for char in lower_text:
        if char == ' ':
            continue  # 'skipping spaces'

        char_counts[char] = char_counts.get(char, 0) + 1  # 'increment count'

        current_count = char_counts[char]
        if current_count > max_count:
            max_count = current_count  # 'updating max count'
            most_freq_char = char
        elif current_count == max_count:
            # 'handle ties: keep first encountered'
            if not most_freq_char:  # 'first character ever'
                most_freq_char = char
            else: # 'already has a character at max count, keep it'
                pass # 'no change needed'

    if not most_freq_char and text:
        # 'edge case: string with only spaces'
        # 'or an empty string'
        for char in text:
            if char != ' ':
                return char # 'return first non-space if all counts are 1'
        return '' # 'only spaces or empty string'

    return most_freq_char

