def is_leap_year(year):
    if not isinstance(year, int):
        raise TypeError('Year must be an integer.')
    if year < 0:
        raise ValueError('Year must be a non-negative number.')

    if year % 4 == 0:
        if year % 100 == 0:
            if year % 400 == 0:
                return True
            else:
                return False
        else:
            return True
    else:
        return False

def test_leap_year():
    assert is_leap_year(2000) is True, '2000 should be a leap year.'
    assert is_leap_year(1900) is False, '1900 should not be a leap year.'
    assert is_leap_year(2004) is True, '2004 should be a leap year.'
    assert is_leap_year(2007) is False, '2007 should not be a leap year.'
    assert is_leap_year(1600) is True, '1600 should be a leap year.'
    assert is_leap_year(2023) is False, '2023 is not a leap year.'
