def sort_dict_by_value(d):
    'Sorts a dictionary by its values in ascending order.'
    if not isinstance(d, dict):
        raise TypeError('Input must be a dictionary.')
    if not d:
        return []

    items_list = list(d.items())
    sorted_items = sorted(items_list, key=lambda item: item[1])
    return sorted_items

def test_sort_dict():
    'Tests the sort_dict_by_value function.'
    assert sort_dict_by_value({'a': 3, 'b': 1, 'c': 2}) == [('b', 1), ('c', 2), ('a', 3)], 'Test Case 1 Failed'
