    assert sort_dict_by_value({'x': 10, 'y': 5, 'z': 15}) == [('y', 5), ('x', 10), ('z', 15)], 'Another test failed'
    assert sort_dict_by_value({'p': -1, 'q': -5, 'r': 0}) == [('q', -5), ('p', -1), ('r', 0)], 'Negative values test'
