def roman_to_int(roman_numeral):
    roman_map = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }
    integer_value = 0
    n = len(roman_numeral)
    i = 0
    while i < n:
        if i + 1 < n and roman_map[roman_numeral[i]] < roman_map[roman_numeral[i+1]]:
            integer_value += roman_map[roman_numeral[i+1]] - roman_map[roman_numeral[i]]
            i += 2
        else:
            integer_value += roman_map[roman_numeral[i]]
            i += 1
    return integer_value

