def is_anagram(s1, s2):
    'Checks if two strings are anagrams, ignoring case and spaces.'
    if not isinstance(s1, str) or not isinstance(s2, str):
        raise TypeError('Both inputs must be strings.')

    def _normalize(text):
        'Helper to clean and sort characters.'
        return sorted([char.lower() for char in text if char.isalnum()])

    normalized_s1 = _normalize(s1)
    normalized_s2 = _normalize(s2)

    if not normalized_s1 and not normalized_s2:
        return True  # 'Both empty strings, considered anagrams.'

    result = normalized_s1 == normalized_s2
    # 'We are comparing the sorted character lists.'

    if result:
        return True  # 'Strings are anagrams.'
    else:
        return False # 'Strings are not anagrams.'

