def is_valid_url(url):
    schemes = ['http://', 'https://']
    is_valid_scheme = False
    for scheme in schemes:
        if url.startswith(scheme):
            is_valid_scheme = True
            break

    if not is_valid_scheme:
        return False

    after_scheme_part = None
    if url.startswith('http://'):
        after_scheme_part = url[len('http://'):]
    elif url.startswith('https://'):
        after_scheme_part = url[len('https://'):]
    else:
        return False # Should not happen if is_valid_scheme is True

    if '.' in after_scheme_part:
        return True
    else:
        return False

