def encrypt_shift(text, shift):
    result = []
    for char in text:
        if 'a' <= char <= 'z':
            start = ord('a')
            shifted_ord = (ord(char) - start + shift) % 26 + start
            result.append(chr(shifted_ord))
        elif 'A' <= char <= 'Z':
            start = ord('A')
            shifted_ord = (ord(char) - start + shift) % 26 + start
            result.append(chr(shifted_ord))
        else:
            result.append(char)
    return ''.join(result)

if __name__ == '__main__':
    assert encrypt_shift('abc', 1) == 'bcd', 'Test Case 1 Failed: basic lowercase shift'
    assert encrypt_shift('XYZ', 3) == 'ABC', 'Test Case 2 Failed: basic uppercase wrap-around'
    assert encrypt_shift('Hello, World!', 5) == 'Mjqqt, Btwqi!', 'Test Case 3 Failed: mixed case and non-alphabetic'
    assert encrypt_shift('123', 10) == '123', 'Test Case 4 Failed: numbers should not change'
    assert encrypt_shift('', 7) == '', 'Test Case 5 Failed: empty string'
