def sum_two_smallest(numbers):
    'Calculates the sum of the two smallest positive numbers in a list.'
    if len(numbers) < 4:
        raise ValueError('The input list must contain at least four numbers.')

    smallest = float('inf')
    second_smallest = float('inf')

    for num in numbers:
        if not isinstance(num, int) or num <= 0:
            raise ValueError('All numbers in the list must be positive integers.')
        if num < smallest:
            second_smallest = smallest
            smallest = num
        elif num < second_smallest:
            second_smallest = num

