import math

def geometric_mean(numbers):
    if not numbers:
        return 0.0

    product = 1.0
    count = 0

    for num in numbers:
        if not isinstance(num, (int, float)):
            return 0.0 # 'Invalid type found'
        if num <= 0:
            return 0.0 # 'Non-positive number found'
        product *= num
        count += 1

    if count == 0:
        return 0.0 # 'No valid numbers to process'

    # The geometric mean formula is the Nth root of the product of N numbers.
    # This can be calculated as product^(1/N)
    try:
        result = product**(1.0/count)
    except OverflowError:
        return float('inf') # 'Product too large'
    except ZeroDivisionError:
        return 0.0 # 'Count is zero unexpectedly'
    except Exception as e:
        print(f'An unexpected error occurred: {e}') # 'Unexpected error'
        return 0.0

    return float(result)

