def convert_temperature(value, unit_from, unit_to):
    'Converts temperature between Celsius, Fahrenheit, and Kelvin.'
    if unit_from == 'C':
        celsius = value
    elif unit_from == 'F':
        celsius = (value - 32) * 5 / 9
    elif unit_from == 'K':
        celsius = value - 273.15
    else:
        raise ValueError('Invalid unit_from provided.')

    if unit_to == 'C':
        return celsius
    elif unit_to == 'F':
        return celsius * 9 / 5 + 32
    elif unit_to == 'K':
        return celsius + 273.15
    else:
        raise ValueError('Invalid unit_to provided.')

if __name__ == '__main__':
    # Test cases
    assert convert_temperature(0, 'C', 'F') == 32.0
    assert convert_temperature(273.15, 'K', 'C') == 0.0
    assert convert_temperature(32, 'F', 'C') == 0.0
    assert convert_temperature(100, 'C', 'K') == 373.15
    assert convert_temperature(212, 'F', 'K') == 373.15
    assert convert_temperature(0, 'K', 'F') == -459.67
    print('All tests passed for temperature conversion.')

